import { createClient } from 'supabase';
async function sha(s:string){const d=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s));return [...new Uint8Array(d)].map(b=>b.toString(16).padStart(2,'0')).join('')}
Deno.serve(async req=>{const ks=JSON.parse(Deno.env.get('SUPABASE_SECRET_KEYS')||'{}'),sb=createClient(Deno.env.get('SUPABASE_URL')!,ks.default||Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!,{auth:{persistSession:false}}),token=new URL(req.url).searchParams.get('t')||'';const {data:set}=await sb.from('app_settings').select('value').eq('key','dashboard_access').single();if(!token||await sha(token)!==set?.value?.sha256)return new Response('Not found',{status:404});const {data:mv}=await sb.from('model_versions').select('id,version').eq('is_active',true).single();const {data:latest}=await sb.from('model_predictions').select('generated_at,gameweek').eq('model_version_id',mv.id).order('generated_at',{ascending:false}).limit(1).single();const {data:sm}=await sb.from('squad_members').select('player_id').eq('active',true),ids=(sm||[]).map((x:any)=>x.player_id);const [{data:pls},{data:teams},{data:preds}]=await Promise.all([sb.from('players').select('id,web_name,position,team_id').in('id',ids),sb.from('teams').select('id,name'),sb.from('model_predictions').select('*').eq('model_version_id',mv.id).eq('gameweek',latest.gameweek).eq('generated_at',latest.generated_at).in('player_id',ids)]);const tm=new Map(teams.map((x:any)=>[x.id,x.name])),pm=new Map(preds.map((x:any)=>[x.player_id,x])),s=pls.map((p:any)=>({...p,team:tm.get(p.team_id),...pm.get(p.id)})).sort((a:any,b:any)=>b.expected_points-a.expected_points);const rows=s.map((x:any,i:number)=>`<tr><td>${i+1}</td><td><b>${x.web_name}</b><small>${x.team} · ${x.position}</small></td><td>${(+x.expected_minutes).toFixed(0)}</td><td><b>${(+x.expected_points).toFixed(2)}</b></td><td>${(100*x.p_10_plus).toFixed(1)}%</td><td>${(100*x.p_15_plus).toFixed(1)}%</td><td>${(100*x.p_dc).toFixed(1)}%</td></tr>`).join('');const html=`<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#07111f"><title>Football Intelligence</title><style>body{margin:0;background:#07111f;color:#eaf2ff;font-family:system-ui}.w{max-width:900px;margin:auto;padding:18px}h1{font-size:22px;margin-bottom:2px}.m,small{color:#8fa6c4}table{width:100%;border-collapse:collapse;margin-top:18px;background:#0e1b2d;border-radius:14px;overflow:hidden;font-size:12px}th,td{padding:10px 7px;border-bottom:1px solid #182e49;text-align:right}th:nth-child(2),td:nth-child(2){text-align:left}small{display:block;font-size:9px}.note{margin-top:14px;padding:10px;background:#302515;border-radius:10px;color:#ffd98c}</style></head><body><div class="w"><h1>Football Intelligence</h1><div class="m">FPL Engine · v${mv.version} · GW${latest.gameweek}</div><div class="note">GW1 is a post-deadline development run and excluded from predictive backtesting.</div><table><thead><tr><th>#</th><th>Player</th><th>xMin</th><th>xPts</th><th>10+</th><th>15+</th><th>DC</th></tr></thead><tbody>${rows}</tbody></table></div></body></html>`;return new Response(html,{headers:{'Content-Type':'text/html; charset=utf-8','Content-Disposition':'inline','X-Content-Type-Options':'nosniff','Cache-Control':'no-store'}})});
